import React, { useState } from "react";
import { useNavigate, Link } from "react-router-dom";
import { Mail, Lock, Eye, EyeOff, ArrowRight } from "lucide-react";
import { motion } from "framer-motion";
import toast from "react-hot-toast";
import AuthLayout from "../../layouts/AuthLayout";

const Login = () => {
    const navigate = useNavigate();
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [showPassword, setShowPassword] = useState(false);
    const [rememberMe, setRememberMe] = useState(false);
    const [errors, setErrors] = useState({});
    const [isLoading, setIsLoading] = useState(false);

    const validateForm = () => {
        const newErrors = {};

        if (!email) {
            newErrors.email = "Email is required";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
            newErrors.email = "Please enter a valid email";
        }

        if (!password) {
            newErrors.password = "Password is required";
        } else if (password.length < 6) {
            newErrors.password = "Password must be at least 6 characters";
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!validateForm()) {
            return;
        }

        setIsLoading(true);

        setTimeout(() => {
            if (email === "admin@aquaflow.com" && password === "password") {
                localStorage.setItem("userRole", "superAdmin");
                localStorage.setItem("userEmail", email);
                toast.success("Welcome back, Admin!");
                navigate("/admin/dashboard");
            } else if (email === "community@aquaflow.com" && password === "password") {
                localStorage.setItem("userRole", "communityAdmin");
                localStorage.setItem("userEmail", email);
                toast.success("Welcome back, Community Manager!");
                navigate("/community/dashboard");
            } else if (email === "resident@aquaflow.com" && password === "password") {
                localStorage.setItem("userRole", "resident");
                localStorage.setItem("userEmail", email);
                toast.success("Welcome back!");
                navigate("/resident/dashboard");
            } else {
                toast.error("Invalid email or password");
            }
            setIsLoading(false);
        }, 1000);
    };

    const containerVariants = {
        hidden: { opacity: 0, y: 20 },
        visible: {
            opacity: 1,
            y: 0,
            transition: { duration: 0.6, staggerChildren: 0.1 },
        },
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 10 },
        visible: { opacity: 1, y: 0, transition: { duration: 0.4 } },
    };

    return (
        <AuthLayout>
            <motion.div
                variants={containerVariants}
                initial="hidden"
                animate="visible"
                className="w-full max-w-md space-y-6"
            >
                {/* Header */}
                <motion.div variants={itemVariants} className="space-y-2">
                    <h1 className="text-2xl font-bold text-gray-900">Welcome Back</h1>
                    <p className="text-sm text-gray-600">
                        Sign in to your account to continue
                    </p>
                </motion.div>

                {/* Login Card */}
                <motion.div
                    variants={itemVariants}
                    className="relative group"
                >
                    <div className="absolute inset-0 bg-gradient-to-r from-teal-600 to-cyan-600 rounded-xl blur opacity-0 group-hover:opacity-10 transition-all duration-300" />
                    <div className="relative bg-white border border-gray-200 rounded-xl p-6 space-y-5">
                        <form onSubmit={handleSubmit} className="space-y-4">
                            {/* Email */}
                            <motion.div variants={itemVariants} className="space-y-2">
                                <label className="block text-sm font-semibold text-gray-900">
                                    Email Address
                                </label>
                                <div className="relative">
                                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                                    <input
                                        type="email"
                                        value={email}
                                        onChange={(e) => setEmail(e.target.value)}
                                        placeholder="name@company.com"
                                        className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:bg-white transition-all text-sm"
                                    />
                                </div>
                                {errors.email && (
                                    <p className="text-xs text-red-500 font-medium">{errors.email}</p>
                                )}
                            </motion.div>

                            {/* Password */}
                            <motion.div variants={itemVariants} className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <label className="block text-sm font-semibold text-gray-900">
                                        Password
                                    </label>
                                    <button
                                        type="button"
                                        className="text-xs text-teal-600 hover:text-teal-700 font-medium transition-colors"
                                    >
                                        Forgot password?
                                    </button>
                                </div>
                                <div className="relative">
                                    <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
                                    <input
                                        type={showPassword ? "text" : "password"}
                                        value={password}
                                        onChange={(e) => setPassword(e.target.value)}
                                        placeholder="••••••••"
                                        className="w-full pl-10 pr-10 py-2.5 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-teal-500 focus:bg-white transition-all text-sm"
                                    />
                                    <button
                                        type="button"
                                        onClick={() => setShowPassword(!showPassword)}
                                        className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 transition-colors"
                                    >
                                        {showPassword ? (
                                            <EyeOff className="w-5 h-5" />
                                        ) : (
                                            <Eye className="w-5 h-5" />
                                        )}
                                    </button>
                                </div>
                                {errors.password && (
                                    <p className="text-xs text-red-500 font-medium">{errors.password}</p>
                                )}
                            </motion.div>

                            {/* Remember Me */}
                            <motion.div variants={itemVariants} className="flex items-center gap-2">
                                <input
                                    type="checkbox"
                                    id="remember"
                                    checked={rememberMe}
                                    onChange={(e) => setRememberMe(e.target.checked)}
                                    className="w-4 h-4 rounded border-gray-300 text-teal-600 focus:ring-2 focus:ring-teal-500"
                                />
                                <label htmlFor="remember" className="text-sm text-gray-700">
                                    Remember me for 30 days
                                </label>
                            </motion.div>

                            {/* Submit Button */}
                            <motion.button
                                variants={itemVariants}
                                whileHover={{ scale: 1.01 }}
                                whileTap={{ scale: 0.99 }}
                                type="submit"
                                disabled={isLoading}
                                className="w-full py-2.5 bg-gradient-to-r from-teal-600 to-teal-700 text-white font-semibold rounded-lg hover:shadow-lg hover:shadow-teal-200 transition-all duration-200 flex items-center justify-center gap-2 disabled:opacity-50 disabled:cursor-not-allowed text-sm"
                            >
                                {isLoading ? (
                                    <>
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                        Signing in...
                                    </>
                                ) : (
                                    <>
                                        Sign In
                                        <ArrowRight className="w-4 h-4" />
                                    </>
                                )}
                            </motion.button>
                        </form>

                        {/* Divider */}
                        <div className="relative py-2">
                            <div className="absolute inset-0 flex items-center">
                                <div className="w-full border-t border-gray-200" />
                            </div>
                            <div className="relative flex justify-center text-xs">
                                <span className="px-2 bg-white text-gray-600">
                                    New to AquaFlow?
                                </span>
                            </div>
                        </div>

                        {/* Sign Up Link */}
                        <Link
                            to="/register"
                            className="w-full py-2.5 border-2 border-gray-200 text-gray-900 font-semibold rounded-lg hover:border-teal-600 hover:text-teal-600 transition-all duration-200 text-center text-sm block"
                        >
                            Create Account
                        </Link>
                    </div>
                </motion.div>

                {/* Footer */}
                <motion.p variants={itemVariants} className="text-center text-xs text-gray-600">
                    By signing in, you agree to our{" "}
                    <button className="text-teal-600 hover:text-teal-700 font-medium">
                        Terms of Service
                    </button>{" "}
                    and{" "}
                    <button className="text-teal-600 hover:text-teal-700 font-medium">
                        Privacy Policy
                    </button>
                </motion.p>

                {/* Demo Credentials */}
                <motion.div variants={itemVariants} className="mt-6 p-3 bg-teal-50 border border-teal-200 rounded-lg">
                    <p className="text-xs font-semibold text-teal-900 mb-2">Demo Credentials:</p>
                    <div className="space-y-1 text-xs text-teal-800">
                        <p>Admin: admin@aquaflow.com / password</p>
                        <p>Community: community@aquaflow.com / password</p>
                        <p>Resident: resident@aquaflow.com / password</p>
                    </div>
                </motion.div>
            </motion.div>
        </AuthLayout>
    );
};

export default Login;
